import{_ as e,o as r,c as n,ao as a}from"./chunks/framework.8Wkhwg0B.js";const m=JSON.parse('{"title":"QuantumEngine","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":null}'),i={name:"index.md"};function o(d,t,s,u,l,c){return r(),n("div",null,[...t[0]||(t[0]=[a('<h1 id="QuantumEngine" tabindex="-1">QuantumEngine <a class="header-anchor" href="#QuantumEngine" aria-label="Permalink to &quot;QuantumEngine {#QuantumEngine}&quot;">​</a></h1><p>QuantumEngine is a quantum-chemistry program in pure Julia, under the MIT license: a rewrite of the Rust program <code>quantum_engine</code>, whose outputs serve as its test oracle. It requires Julia 1.13 or later. Its dependencies are JSON, LinearAlgebra, Parsers, Printf, StaticArrays and StrictMode, and their closure holds no <code>_jll</code> package and no artifact outside the standard libraries. YAML.jl is an optional dependency, read through a package extension once it is loaded; its closure brings Libiconv_jll and so stays outside the core (see <a href="./dependencies">Dependencies</a>).</p><h2 id="Errors" tabindex="-1">Errors <a class="header-anchor" href="#Errors" aria-label="Permalink to &quot;Errors {#Errors}&quot;">​</a></h2><p>Every error QuantumEngine throws, besides <code>ArgumentError</code>, is a subtype of <a href="/PureAtomistic.jl/QuantumEngine/dev/api#QuantumEngine.Errors.QuantumEngineError"><code>QuantumEngineError</code></a>. Each prints its message after a prefix that names its kind:</p><table tabindex="0"><thead><tr><th style="text-align:right;">type</th><th style="text-align:right;">printed as</th></tr></thead><tbody><tr><td style="text-align:right;"><a href="/PureAtomistic.jl/QuantumEngine/dev/api#QuantumEngine.Errors.InputError"><code>InputError</code></a></td><td style="text-align:right;"><code>input: &lt;source&gt;:&lt;line&gt;: &lt;msg&gt;</code> (<code>input: &lt;source&gt;: &lt;msg&gt;</code> without a line)</td></tr><tr><td style="text-align:right;"><a href="/PureAtomistic.jl/QuantumEngine/dev/api#QuantumEngine.Errors.BasisError"><code>BasisError</code></a></td><td style="text-align:right;"><code>basis: &lt;msg&gt;</code></td></tr><tr><td style="text-align:right;"><a href="/PureAtomistic.jl/QuantumEngine/dev/api#QuantumEngine.Errors.SCFNotConverged"><code>SCFNotConverged</code></a></td><td style="text-align:right;"><code>scf: &lt;msg&gt;</code></td></tr><tr><td style="text-align:right;"><a href="/PureAtomistic.jl/QuantumEngine/dev/api#QuantumEngine.Errors.OptimizationFailed"><code>OptimizationFailed</code></a></td><td style="text-align:right;"><code>optimization: &lt;msg&gt;</code></td></tr><tr><td style="text-align:right;"><a href="/PureAtomistic.jl/QuantumEngine/dev/api#QuantumEngine.Errors.NotImplemented"><code>NotImplemented</code></a></td><td style="text-align:right;"><code>not implemented (&lt;section&gt;): &lt;msg&gt;</code></td></tr><tr><td style="text-align:right;"><a href="/PureAtomistic.jl/QuantumEngine/dev/api#QuantumEngine.Errors.FunctionalUnavailable"><code>FunctionalUnavailable</code></a></td><td style="text-align:right;"><code>functional: &lt;msg&gt;</code></td></tr><tr><td style="text-align:right;"><a href="/PureAtomistic.jl/QuantumEngine/dev/api#QuantumEngine.Errors.NumericalError"><code>NumericalError</code></a></td><td style="text-align:right;"><code>numerical: &lt;msg&gt;</code></td></tr></tbody></table><p>An <a href="/PureAtomistic.jl/QuantumEngine/dev/api#QuantumEngine.Errors.InputWarning"><code>InputWarning</code></a> records an input that lenient mode accepted where strict mode throws; it is shown as the <code>InputError</code> of the same source, line and message.</p>',6)])])}const h=e(i,[["render",o]]);export{m as __pageData,h as default};
